"""Static HTML dashboard: every scored run, per company, with what was caught and missed.

`python -m spendradar dashboard` reads evidence/evals/*.json (committed scorecards) and, when present,
runs/<id>/ (local run state and reports), and writes evidence/dashboard.html. One self-contained file,
no server, no external assets. Every number on it is copied from a scorecard or a run's state.
"""

from __future__ import annotations

import html
import json
from datetime import datetime
from pathlib import Path

EVALS = Path("evidence/evals")
OUT = Path("evidence/dashboard.html")

LABELS = {
    "budget_total_mismatch": "Budget row total ≠ sum of months",
    "invoice_total_mismatch": "Invoice line items ≠ stated total",
    "invoice_miscategorised": "Invoice billed to the wrong cost centre",
    "invoice_miscategorised_single_vendor": "Wrong cost centre, vendor appears once",
    "invoice_scanned": "Scanned invoice (no text layer)",
    "invoice_corrupt": "Corrupt or empty PDF",
    "invoice_duplicate": "Same invoice sent twice",
    "fixture_sentry_marketing_x5": "Fixture: competitor headcount ×5",
}


def _e(x: object) -> str:
    return html.escape(str(x))


def _load_runs() -> list[dict]:
    """One row per scored run; a run scored more than once keeps its latest scorecard."""
    rows: dict[str, dict] = {}
    for p in sorted(EVALS.glob("2026*.json")):
        card = json.loads(p.read_text(encoding="utf-8"))
        for r in card.get("runs", []):
            if "planted_detail" not in r:
                continue
            dataset = r.get("dataset") or "acme"
            rows[r["run_id"]] = {**r, "dataset": dataset, "variant": card.get("variant", ""),
                                 "scorecard": p.name, "created": card.get("created", "")}
    return sorted(rows.values(), key=lambda r: (r["dataset"], r["created"]))


def _company(dataset: str) -> tuple[str, str]:
    truth = Path("evals/ground_truth.json" if dataset == "acme" else f"evals/ground_truth_{dataset}.json")
    if dataset == "acme":
        return "Acme Observability Inc.", "observability SaaS (development set)"
    if truth.exists():
        t = json.loads(truth.read_text(encoding="utf-8"))
        return t.get("company", dataset), t.get("industry", "") + " (held out)"
    return dataset, ""


def _state(run_id: str) -> dict | None:
    p = Path(f"runs/{run_id}/state.json")
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else None


def _run_card(r: dict) -> str:
    caught, total = r["planted_caught"], r["planted_total"]
    fa = r.get("false_alarms", "—")
    cells = "".join(
        f"<li class='{'ok' if v else 'miss'}'><span>{'✓' if v else '✗'}</span>{_e(LABELS.get(k, k))}</li>"
        for k, v in r["planted_detail"].items())
    st = _state(r["run_id"])
    extra = ""
    if st:
        fnd = [f for f in st["findings"] if f["id"].startswith(("f_cat", "f_dup", "f_totals"))]
        extra += "<details><summary>Internal findings</summary><ul class='plain'>" + "".join(
            f"<li><b>{_e(f['status'])}</b> · {_e(f['statement'][:220])}</li>" for f in fnd) + "</ul></details>"
        decs = st.get("decisions", [])
        if decs:
            extra += "<details><summary>Recovery decisions ({} · {} not the rule default)</summary><ul class='plain'>".format(
                len(decs), sum(d["chosen"] != d["default"] for d in decs)) + "".join(
                f"<li><code>{_e(d['task_id'])}</code> chose <b>{_e(d['chosen'])}</b>"
                f"{' (rule default: ' + _e(d['default']) + ')' if d['chosen'] != d['default'] else ''}"
                f" — {_e((d.get('reason') or '')[:160])}</li>" for d in decs) + "</ul></details>"
        if Path(f"runs/{r['run_id']}/report.html").exists():
            extra += f"<p><a href='../runs/{_e(r['run_id'])}/report.html'>Open the full report</a> (local file)</p>"
    return (f"<article class='run'><header><code>{_e(r['run_id'])}</code> <span class='tag'>{_e(r['variant'])}</span>"
            f"<span class='muted'> commit {_e(r['git_sha'])}</span></header>"
            f"<div class='stats'><div><b>{caught}/{total}</b><small>planted errors caught</small></div>"
            f"<div><b>{_e(fa)}</b><small>false alarms</small></div>"
            f"<div><b>{_e(r['unsupported_numbers_in_report'])}</b><small>unsourced numbers</small></div>"
            f"<div><b>{_e(r['llm_calls'])}</b><small>LLM calls · {_e(r.get('fallback_hops', 0))} fallbacks</small></div>"
            f"<div><b>{r['crustdata_credits']:.1f}</b><small>Crustdata credits</small></div></div>"
            f"<ul class='checks'>{cells}</ul>"
            f"<p class='muted'>neatlogs trace <code>{_e(r['trace_id'])}</code> · scorecard <code>{_e(r['scorecard'])}</code></p>"
            f"{extra}</article>")


def build() -> Path:
    runs = _load_runs()
    by_ds: dict[str, list[dict]] = {}
    for r in runs:
        by_ds.setdefault(r["dataset"], []).append(r)
    order = ["acme"] + sorted(k for k in by_ds if k != "acme")
    summary_rows = []
    sections = []
    for ds in [d for d in order if d in by_ds]:
        name, industry = _company(ds)
        rs = by_ds[ds]
        first, last = rs[0], rs[-1]
        summary_rows.append(
            f"<tr><td><b>{_e(name)}</b><br><small class='muted'>{_e(industry)}</small></td>"
            f"<td>{first['planted_caught']}/{first['planted_total']}<br><small class='muted'>{_e(first['variant'])}</small></td>"
            f"<td>{last['planted_caught']}/{last['planted_total']}<br><small class='muted'>{_e(last['variant'])}</small></td>"
            f"<td>{_e(last.get('false_alarms', '—'))}</td><td>{len(rs)}</td></tr>")
        sections.append(f"<section><h2>{_e(name)} <small class='muted'>{_e(industry)}</small></h2>"
                        + "".join(_run_card(r) for r in reversed(rs)) + "</section>")
